package com.duozhi.outbound;

import java.util.*;
import java.time.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;

@RestController
@AdminPermission("product:write")
@RequestMapping("/api/v1/product")
public class ProductOperations {
    private final Store store;private final Transactions tx;private final Contract contract;private final JsonSupport json;private final ConversationPolicy product;private final Outbox outbox;private final AiRuntime ai;private final HumanRouting routing;
    public ProductOperations(Store store,Transactions tx,Contract contract,JsonSupport json,ConversationPolicy product,Outbox outbox,AiRuntime ai,HumanRouting routing){this.store=store;this.tx=tx;this.contract=contract;this.json=json;this.product=product;this.outbox=outbox;this.ai=ai;this.routing=routing;}
    private Identity admin(HttpServletRequest request){Identity i=Identity.from(request);i.admin("product:write");return i;}
    private void campaign(long tenant,Object id){if(id!=null)store.require("campaign",tenant,id);}
    @SuppressWarnings("unchecked") private Map<String,Object> normalize(Map<String,Object> raw){
        Map<String,Object> policy=contract.input("ScenarioPolicy",raw,true);
        policy.putIfAbsent("weekdays",Arrays.asList(0,1,2,3,4,5,6));policy.putIfAbsent("holidays",new ArrayList<>());policy.putIfAbsent("handoff_agent_ids",new ArrayList<>());policy.putIfAbsent("slots",new ArrayList<>());policy.putIfAbsent("faqs",new LinkedHashMap<>());policy.putIfAbsent("retry_seconds",JsonSupport.map("busy",1800,"no_answer",3600,"voicemail",86400));policy.putIfAbsent("permanent_causes",Arrays.asList("UNALLOCATED_NUMBER","INVALID_NUMBER_FORMAT","NUMBER_CHANGED","CALL_REJECTED"));
        try{ZoneId.of(policy.get("timezone").toString());for(Object date:(List<?>)policy.get("holidays"))LocalDate.parse(date.toString());}catch(DateTimeException e){throw new ApiError(400,"invalid business calendar");}
        if(JsonSupport.integer(policy.get("start_hour"),9)>=JsonSupport.integer(policy.get("end_hour"),20))throw new ApiError(400,"invalid business calendar");for(Object day:(List<?>)policy.get("weekdays"))if(!(day instanceof Number)||((Number)day).intValue()<0||((Number)day).intValue()>6)throw new ApiError(400,"invalid business calendar");
        List<Map<String,Object>> slots=new ArrayList<>();Set<Object> keys=new HashSet<>();for(Map<String,Object> rawSlot:(List<Map<String,Object>>)policy.get("slots")){Map<String,Object> slot=contract.input("SlotDefinition",rawSlot,true);slot.putIfAbsent("choices",new ArrayList<>());slot.putIfAbsent("qualifies",new ArrayList<>());if(!keys.add(slot.get("key")))throw new ApiError(400,"duplicate field key");if("choice".equals(slot.get("kind"))&&((List<?>)slot.get("choices")).isEmpty()||!((List<?>)slot.get("choices")).containsAll((List<?>)slot.get("qualifies")))throw new ApiError(400,"invalid slot choices");slots.add(contract.output("SlotDefinition",slot));}policy.put("slots",slots);
        Map<String,Object> faqs=(Map<String,Object>)policy.get("faqs");if(faqs.size()>50)throw new ApiError(400,"invalid FAQ");for(Map.Entry<String,Object> e:faqs.entrySet())if(e.getKey().isEmpty()||e.getKey().length()>100||!(e.getValue() instanceof String)||e.getValue().toString().length()>2000)throw new ApiError(400,"invalid FAQ");
        for(Map.Entry<String,Object> e:((Map<String,Object>)policy.get("retry_seconds")).entrySet())if(!Values.set("busy","no_answer","voicemail","failed").contains(e.getKey())||!(e.getValue() instanceof Integer)||((Integer)e.getValue())<60||((Integer)e.getValue())>604800)throw new ApiError(400,"invalid retry policy");
        Map<String,Object> result=contract.output("ScenarioPolicy",policy);result.putAll(HumanRouting.options(raw));return result;
    }
    @GetMapping("/policy") public Map<String,Object> policy(@RequestParam(required=false) Long campaign_id,HttpServletRequest request){Identity i=admin(request);campaign(i.tenant(),campaign_id);Map<String,Object> current=product.current(i.tenant(),campaign_id);List<Map<String,Object>> history=new ArrayList<>();for(Map<String,Object> row:store.query("scenarioversion","policyHistory",JsonSupport.map("tenantId",i.tenant(),"campaignId",campaign_id)))history.add(JsonSupport.map("id",row.get("id"),"created_at",row.get("created_at"),"policy",normalize(json.object(row.get("policy_json").toString()))));return JsonSupport.map("policy",normalize(cast(current.get("policy"))),"version_id",current.get("version"),"history",history);}
    @SuppressWarnings("unchecked") private Map<String,Object> cast(Object object){return (Map<String,Object>)object;}
    @PostMapping("/policy") public Map<String,Object> savePolicy(@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=admin(request);Map<String,Object> input=contract.input("ScenarioSave",raw,true),policy=normalize(cast(input.get("policy")));return tx.serialized(()->{
        tx.platform();tx.tenant(i.tenant());campaign(i.tenant(),input.get("campaign_id"));Map<String,Object> current=product.current(i.tenant(),input.get("campaign_id"));
        if(!Objects.toString(current.get("version"),"").equals(Objects.toString(input.get("expected_version_id"),"")))throw new ApiError(409,"策略已更新，请刷新后重试");
        for(Object id:(List<?>)policy.get("handoff_agent_ids")){Map<String,Object> agent=store.one("user","sourceProductOperations30_1",Store.queryParameters(0,i.tenant(),id));if(agent==null||!"agent".equals(agent.get("role"))||!Boolean.TRUE.equals(agent.get("enabled")))throw new ApiError(422,"转接坐席不属于本租户或不可用");}
        routing.validate(i.tenant(),policy);Map<String,Object> snapshot=new LinkedHashMap<>(policy);List<Map<String,Object>> knowledge=store.query("knowledgeitem","sourceProductOperations31_2",Store.queryParameters(0,i.tenant(),true,input.get("campaign_id")));snapshot.put("_knowledge",knowledge);if(knowledge.size()>500||json.json(snapshot).getBytes(java.nio.charset.StandardCharsets.UTF_8).length>600000)throw new ApiError(422,"知识内容过多，请按活动拆分适用范围后发布");
        Map<String,String> samples=Values.map("不用转人工","decline_handoff","我需要你们别再打","stop_contact","可以听一下","permission_to_listen","你说的是需要先交钱吗","question","我不需要，不对，我现在需要","interested");for(Map.Entry<String,String> e:samples.entrySet())if(!e.getValue().equals(DialogueRules.classify(e.getKey())))throw new ApiError(409,"基础业务样例未通过，不能发布");snapshot.put("_checks",JsonSupport.map("semantic_examples",samples.size(),"passed",true));
        Map<String,Object> row=store.insert("scenarioversion",JsonSupport.map("tenant_id",i.tenant(),"campaign_id",input.get("campaign_id"),"policy_json",json.json(snapshot),"published_by",i.userId()));return JsonSupport.map("version_id",row.get("id"),"policy",policy);
    });}
    private static class Simulation extends RuntimeException{final Map<String,Object> result;Simulation(Map<String,Object> result){this.result=result;}}
    @PostMapping("/simulate") public Map<String,Object> simulate(@RequestBody Map<String,Object> raw,HttpServletRequest request){admin(request);Map<String,Object> input=contract.input("ScenarioProbe",raw,true),policy=normalize(cast(input.get("policy")));
        try{tx.serialized(()->{
            tx.platform();long tenant=-Math.abs(UUID.randomUUID().getMostSignificantBits()%2000000000L)-1;store.insert("tenant",JsonSupport.map("id",tenant,"name","simulation","code",UUID.randomUUID().toString()));store.insert("scenarioversion",JsonSupport.map("tenant_id",tenant,"policy_json",json.json(policy)));
            Map<String,Object> call=store.insert("callsession",JsonSupport.map("tenant_id",tenant,"phone","simulation","mode","ai_handoff","status","in_ai","attempts",1)),rt=store.insert("realtimesession",JsonSupport.map("tenant_id",tenant,"call_session_id",call.get("id")));List<Map<String,Object>> trace=new ArrayList<>();int n=0;
            for(Object text:(List<?>)input.get("utterances")){n++;store.update("realtimesession",tenant,rt.get("id"),JsonSupport.map("turn_sequence",n));store.insert("speechturn",JsonSupport.map("tenant_id",tenant,"call_session_id",call.get("id"),"attempt",1,"turn_index",n,"provider_event_key","sim:"+n,"speaker_role","customer","transcript",text,"is_final",true));Map<String,Object> reply=product.prepare(call,text.toString());trace.add(JsonSupport.map("utterance",text,"intent",DialogueRules.classify(text.toString()),"action",reply==null?"model_required":reply.get("action"),"reply",reply==null?"":reply.get("tts_text"),"state",json.object(product.state(call).get("data_json").toString())));if(reply!=null&&Values.set("hangup","handoff").contains(reply.get("action")))break;}
            throw new Simulation(JsonSupport.map("trace",trace,"external_actions_executed",false,"policy_hash",JsonSupport.sha(json.json(policy))));
        });}catch(Simulation finished){return finished.result;}throw new IllegalStateException("simulation must roll back");
    }
    @GetMapping("/appointments") public List<Map<String,Object>> appointments(@RequestParam(defaultValue="1") int page,HttpServletRequest request){long tenant=admin(request).tenant();List<Map<String,Object>> result=store.query("callbackappointment","sourceProductOperations44_3",Store.queryParameters(0,tenant,Contract.page(page,50)));for(Map<String,Object> a:result){Map<String,Object> call=store.require("callsession",tenant,a.get("source_call_id"));a.put("phone",call.get("phone"));}return result;}
    private LocalDateTime utc(Object value){try{return OffsetDateTime.parse(value.toString()).withOffsetSameInstant(ZoneOffset.UTC).toLocalDateTime();}catch(DateTimeException e){throw new ApiError(422,"时间必须包含有效时区");}}
    @PatchMapping("/appointments/{id}") public Map<String,Object> appointment(@PathVariable UUID id,@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=admin(request);Map<String,Object> input=contract.input("AppointmentPatch",raw,true);return tx.serialized(()->{
        tx.platform();Map<String,Object> row=store.require("callbackappointment",i.tenant(),id);if(CallLifecycle.number(row,"revision")!=JsonSupport.integer(input.get("revision"),-1)||!"confirmed".equals(row.get("state")))throw new ApiError(409,"预约状态已变化");Map<String,Object> changes=JsonSupport.map("revision",CallLifecycle.number(row,"revision")+1);
        if(Boolean.TRUE.equals(input.get("cancel")))changes.put("state","cancelled");else if(input.get("scheduled_at")!=null){LocalDateTime value=utc(input.get("scheduled_at"));Map<String,Object> source=store.require("callsession",i.tenant(),row.get("source_call_id")),policy=cast(product.current(i.tenant(),source.get("campaign_id")).get("policy"));if(!value.isAfter(Store.now())||value.isAfter(Store.now().plusDays(90))||!product.inHours(policy,value))throw new ApiError(422,"预约时间不在可用服务时段");changes.put("scheduled_at",value);}else throw new ApiError(422,"需要填写时间或选择取消");
        row=store.update("callbackappointment",i.tenant(),id,changes);if(!Boolean.TRUE.equals(input.get("cancel"))){Map<String,Object> task=outbox.enqueue(i.tenant(),"after_playback",row.get("source_call_id"),"appointment:"+id+":"+row.get("revision"),JsonSupport.map("product_kind","appointment","appointment_id",id,"revision",row.get("revision")));product.schedule(task,LocalDateTime.parse(row.get("scheduled_at").toString()));}return row;
    });}
    @GetMapping("/work-items") public List<Map<String,Object>> work(@RequestParam(defaultValue="1") int page,HttpServletRequest request){return store.query("productworkitem","sourceProductOperations51_4",Store.queryParameters(0,admin(request).tenant(),Contract.page(page,50)));}
    @PatchMapping("/work-items/{id}") public Map<String,Object> work(@PathVariable UUID id,@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=admin(request);Map<String,Object> input=contract.input("WorkPatch",raw,true);return tx.serialized(()->{tx.platform();store.require("productworkitem",i.tenant(),id);if(input.get("assigned_to")!=null&&!Boolean.TRUE.equals(store.require("user",i.tenant(),input.get("assigned_to")).get("enabled")))throw new ApiError(422,"负责人不可用");store.update("productworkitem",i.tenant(),id,input);return new LinkedHashMap<String,Object>();});}
    @PostMapping("/incoming") public Map<String,Object> incoming(@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=Identity.from(request);i.admin("product:write");Map<String,Object> input=contract.input("Incoming",raw,true);String phone=Contacts.phone(input.get("phone")),key=i.tenant()+":"+input.get("kind")+":"+input.get("event_id");return tx.serialized(()->{
        tx.platform();tx.tenant(i.tenant());Map<String,Object> old=store.one("productworkitem","scopedProductOperations54",Store.scopedParameters(i.tenant(),key));if(old!=null){if(!phone.equals(old.get("phone"))||!Objects.equals(json.object(old.get("detail_json").toString()).get("text"),input.get("text")))throw new ApiError(409,"事件标识与内容冲突");return JsonSupport.map("item_id",old.get("id"),"duplicate",true,"route","human_queue");}
        Map<String,Object> call=store.one("callsession","sourceProductOperations55_6",Store.queryParameters(0,i.tenant(),phone));if("sms_reply".equals(input.get("kind"))&&"stop_contact".equals(DialogueRules.classify(input.get("text").toString())))product.suppress(call==null?JsonSupport.map("tenant_id",i.tenant(),"phone",phone,"id",null):call,"sms_stop_contact");
        Map<String,Object> row=store.insert("productworkitem",JsonSupport.map("tenant_id",i.tenant(),"event_key",key,"call_id",call==null?null:call.get("id"),"kind",input.get("kind"),"phone",phone,"detail_json",json.json(JsonSupport.map("text",input.get("text"),"campaign_id",call==null?null:call.get("campaign_id")))));return JsonSupport.map("item_id",row.get("id"),"duplicate",false,"route","human_queue");
    });}
    @GetMapping("/outcomes") public List<Map<String,Object>> outcomes(@RequestParam(defaultValue="1") int page,HttpServletRequest request){long tenant=admin(request).tenant();List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> state:store.query("conversationstate","sourceProductOperations58_7",Store.queryParameters(0,tenant,Contract.page(page,50)))){Map<String,Object> call=store.require("callsession",tenant,state.get("call_id"));result.add(JsonSupport.map("call_id",call.get("id"),"phone",call.get("phone"),"attempt",state.get("attempt"),"policy_version_id",state.get("policy_version_id"),"status",call.get("status"),"data",json.object(state.get("data_json").toString())));}return result;}
    @PostMapping("/knowledge/import") public Map<String,Object> importKnowledge(@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=admin(request);Map<String,Object> input=contract.input("KnowledgeImport",raw,true);campaign(i.tenant(),input.get("campaign_id"));for(String key:Arrays.asList("valid_from","valid_until"))if(input.get(key)!=null)input.put(key,utc(input.get(key)));if(input.get("valid_from")!=null&&input.get("valid_until")!=null&&!((LocalDateTime)input.get("valid_from")).isBefore((LocalDateTime)input.get("valid_until")))throw new ApiError(422,"知识有效期无效");input.put("tenant_id",i.tenant());input.put("created_by",i.userId());return store.insert("knowledgeitem",input);}
    @PostMapping("/knowledge/search") public List<Map<String,Object>> knowledge(@RequestBody Map<String,Object> raw,HttpServletRequest request){Identity i=admin(request);Map<String,Object> input=contract.input("KnowledgeProbe",raw,true);campaign(i.tenant(),input.get("campaign_id"));return ai.knowledge(JsonSupport.map("tenant_id",i.tenant(),"campaign_id",input.get("campaign_id")),Collections.emptyMap(),input.get("query").toString());}
    @GetMapping("/funnel") public Map<String,Object> funnel(@RequestParam(defaultValue="7") int days,HttpServletRequest request){long tenant=admin(request).tenant();if(days<1||days>90)throw new ApiError(400,"invalid days");Object since=store.encode("conversationstate","updated_at",Store.now().minusDays(days));String data=store.lock().isEmpty()?"s.data_json":"CAST(s.data_json AS JSON)";List<Map<String,Object>> groups=store.projection("conversationstate","deliveryFunnel",Values.map("tenantId",tenant,"since",since));Map<String,Object> counts=store.projectOne("callusage","rawProductOperations61_1",Store.queryParameters(0,tenant,since));counts.putAll(JsonSupport.map("days",days,"groups",groups,"definitions","接通按计费接听记录；业务结果按最近更新时间，每组号码去重；同一号码可跨组出现，不能相加作为总人数。"));return counts;}
}
